INSERT INTO public.test_questions (id, test_id, question_text, audio_url, image_url, options, correct_answer, explanation, points, order_index, created_at)
VALUES
('dd5d4c49-d406-4774-abe5-be6473d5a1a1', 'a2288c0d-ed58-4f18-b118-2a9f019e3af9', 'Le gouvernement canadien a récemment dévoilé son plan d''action national pour la transition écologique, un document de 150 pages qui fixe des objectifs ambitieux pour réduire les émissions de gaz à effet de serre de 45% d''ici 2030 par rapport aux niveaux de 2005. Ce plan, qui s''inscrit dans le cadre de l''Accord de Paris, prévoit des investissements majeurs dans les énergies renouvelables, l''électrification des transports et l''efficacité énergétique des bâtiments. Parmi les mesures phares, on trouve l''installation de bornes de recharge pour véhicules électriques sur l''ensemble du territoire, des subventions pour la rénovation énergétique des logements anciens, et un soutien accru à la recherche et développement dans le secteur des technologies vertes. Le gouvernement estime que ces mesures pourraient créer jusqu''à 200 000 emplois dans les prochaines années. Cependant, ce plan fait face à des critiques. Certains groupes environnementaux estiment que les objectifs ne sont pas assez ambitieux, tandis que des représentants du secteur pétrolier s''inquiètent des conséquences économiques pour les régions dépendantes des hydrocarbures.

Question : Quel est l''objectif principal du plan d''action national pour la transition écologique ?', NULL, NULL, '["R\u00e9duire les \u00e9missions de GES de 45% d''ici 2030", "\u00c9liminer compl\u00e8tement les hydrocarbures d''ici 2030", "Cr\u00e9er 500 000 emplois verts", "Atteindre la neutralit\u00e9 carbone en 2025"]', 'Réduire les émissions de GES de 45% d''ici 2030', '''Réduire les émissions de GES de 45% d''ici 2030'' est la réponse correcte d''après le texte fourni.', 1, 0, '2026-07-18T04:12:22.151912'),
('a137346b-c2f0-4f10-ab88-91d6c18e7986', 'a2288c0d-ed58-4f18-b118-2a9f019e3af9', 'Le gouvernement canadien a récemment dévoilé son plan d''action national pour la transition écologique, un document de 150 pages qui fixe des objectifs ambitieux pour réduire les émissions de gaz à effet de serre de 45% d''ici 2030 par rapport aux niveaux de 2005. Ce plan, qui s''inscrit dans le cadre de l''Accord de Paris, prévoit des investissements majeurs dans les énergies renouvelables, l''électrification des transports et l''efficacité énergétique des bâtiments. Parmi les mesures phares, on trouve l''installation de bornes de recharge pour véhicules électriques sur l''ensemble du territoire, des subventions pour la rénovation énergétique des logements anciens, et un soutien accru à la recherche et développement dans le secteur des technologies vertes. Le gouvernement estime que ces mesures pourraient créer jusqu''à 200 000 emplois dans les prochaines années. Cependant, ce plan fait face à des critiques. Certains groupes environnementaux estiment que les objectifs ne sont pas assez ambitieux, tandis que des représentants du secteur pétrolier s''inquiètent des conséquences économiques pour les régions dépendantes des hydrocarbures.

Question : Quelles sont les mesures phares mentionnées dans le plan ?', NULL, NULL, '["L''installation de bornes de recharge, des subventions pour la r\u00e9novation, et le soutien \u00e0 la R&D", "La construction de nouvelles centrales nucl\u00e9aires et l''exportation de p\u00e9trole", "L''interdiction totale des v\u00e9hicules thermiques et la taxation du carbone", "La fermeture des industries polluantes et la d\u00e9localisation"]', 'L''installation de bornes de recharge, des subventions pour la rénovation, et le soutien à la R&D', '''L''installation de bornes de recharge, des subventions pour la rénovation, et le soutien à la R&D'' est la réponse correcte d''après le texte fourni.', 1, 1, '2026-07-18T04:12:22.151962'),
('454fd9d0-b310-4851-bf3f-92db140dc9b1', 'a2288c0d-ed58-4f18-b118-2a9f019e3af9', 'Le gouvernement canadien a récemment dévoilé son plan d''action national pour la transition écologique, un document de 150 pages qui fixe des objectifs ambitieux pour réduire les émissions de gaz à effet de serre de 45% d''ici 2030 par rapport aux niveaux de 2005. Ce plan, qui s''inscrit dans le cadre de l''Accord de Paris, prévoit des investissements majeurs dans les énergies renouvelables, l''électrification des transports et l''efficacité énergétique des bâtiments. Parmi les mesures phares, on trouve l''installation de bornes de recharge pour véhicules électriques sur l''ensemble du territoire, des subventions pour la rénovation énergétique des logements anciens, et un soutien accru à la recherche et développement dans le secteur des technologies vertes. Le gouvernement estime que ces mesures pourraient créer jusqu''à 200 000 emplois dans les prochaines années. Cependant, ce plan fait face à des critiques. Certains groupes environnementaux estiment que les objectifs ne sont pas assez ambitieux, tandis que des représentants du secteur pétrolier s''inquiètent des conséquences économiques pour les régions dépendantes des hydrocarbures.

Question : Combien d''emplois ces mesures pourraient-elles créer selon le gouvernement ?', NULL, NULL, '["50 000", "100 000", "200 000", "500 000"]', '200 000', '''200 000'' est la réponse correcte d''après le texte fourni.', 1, 2, '2026-07-18T04:12:22.151984'),
('89a44b2c-a729-42e6-9ddb-6efee9344121', 'a2288c0d-ed58-4f18-b118-2a9f019e3af9', 'Le gouvernement canadien a récemment dévoilé son plan d''action national pour la transition écologique, un document de 150 pages qui fixe des objectifs ambitieux pour réduire les émissions de gaz à effet de serre de 45% d''ici 2030 par rapport aux niveaux de 2005. Ce plan, qui s''inscrit dans le cadre de l''Accord de Paris, prévoit des investissements majeurs dans les énergies renouvelables, l''électrification des transports et l''efficacité énergétique des bâtiments. Parmi les mesures phares, on trouve l''installation de bornes de recharge pour véhicules électriques sur l''ensemble du territoire, des subventions pour la rénovation énergétique des logements anciens, et un soutien accru à la recherche et développement dans le secteur des technologies vertes. Le gouvernement estime que ces mesures pourraient créer jusqu''à 200 000 emplois dans les prochaines années. Cependant, ce plan fait face à des critiques. Certains groupes environnementaux estiment que les objectifs ne sont pas assez ambitieux, tandis que des représentants du secteur pétrolier s''inquiètent des conséquences économiques pour les régions dépendantes des hydrocarbures.

Question : Quelles sont les principales critiques adressées à ce plan ?', NULL, NULL, '["Il est trop ambitieux pour certains et pas assez pour d''autres", "Il est unanimement soutenu par tous les partis", "Il manque totalement de financement", "Il est jug\u00e9 inconstitutionnel"]', 'Il est trop ambitieux pour certains et pas assez pour d''autres', '''Il est trop ambitieux pour certains et pas assez pour d''autres'' est la réponse correcte d''après le texte fourni.', 1, 3, '2026-07-18T04:12:22.151999'),
('df42b81d-2a31-4dcb-b0a8-a2dbd54f5483', 'a2288c0d-ed58-4f18-b118-2a9f019e3af9', 'L''immigration joue un rôle fondamental dans le développement économique et démographique du Canada. Selon les données publiées par Statistique Canada, le pays a accueilli plus de 430 000 nouveaux résidents permanents en 2023, un chiffre record qui témoigne de la politique d''immigration ambitieuse du gouvernement fédéral. Les provinces qui ont connu la plus forte croissance démographique sont l''Ontario, la Colombie-Britannique et l''Alberta. Les nouveaux arrivants s''installent majoritairement dans les grands centres urbains comme Toronto, Vancouver et Montréal, attirés par les opportunités d''emploi et les services d''établissement. Le système de gestion des demandes d''immigration, basé sur le système de points Entrée express, a été conçu pour attirer des travailleurs qualifiés capables de contribuer rapidement à l''économie canadienne. Les critères de sélection prennent en compte l''âge, le niveau d''éducation, l''expérience professionnelle, les compétences linguistiques en français et en anglais, ainsi que la capacité d''adaptation. « L''immigration n''est pas seulement une nécessité économique, c''est aussi une source d''enrichissement culturel, » a souligné le ministre.

Question : Combien de nouveaux résidents permanents le Canada a-t-il accueilli en 2023 ?', NULL, NULL, '["Plus de 200 000", "Plus de 300 000", "Plus de 430 000", "Plus de 500 000"]', 'Plus de 430 000', '''Plus de 430 000'' est la réponse correcte d''après le texte fourni.', 1, 4, '2026-07-18T04:12:22.152012'),
